function ivPersistentMapping(code,name){const keyCode=ivNorm(code),keyName=ivNorm(name);return inventoryState.itemMappings.find(x=>(keyCode&&ivNorm(x.sourceCode)===keyCode)||(keyName&&ivNorm(x.sourceName)===keyName))}
function ivAutoMatch(code,name){const mapping=ivPersistentMapping(code,name);if(mapping&&ivMenu(mapping.menuItemId))return mapping.menuItemId;const menus=ivPricingMenus(),codeN=ivNorm(code),nameN=ivNorm(name);return menus.find(m=>codeN&&ivNorm(m.code)===codeN)?.id||menus.find(m=>nameN&&ivNorm(m.name)===nameN)?.id||''}
function ivLoadXlsx(){if(window.XLSX)return Promise.resolve(window.XLSX);if(inventoryXlsxPromise)return inventoryXlsxPromise;const sources=['./js/xlsx.full.min.js','https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js','https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js'];inventoryXlsxPromise=new Promise(async(resolve,reject)=>{for(const src of sources){try{await new Promise((ok,fail)=>{const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=fail;document.head.appendChild(s)});if(window.XLSX)return resolve(window.XLSX)}catch(e){}}reject(new Error('کتابخانه خواندن Excel بارگذاری نشد'))});return inventoryXlsxPromise}
function ivHeaderScore(headers){const hs=headers.map(ivNorm),aliases={code:['کدآیتم','کدکالا','کدمحصول','کدغذا'],name:['نامآیتم','نامکالا','ناممحصول','شرحکالا','نامغذا','شرح'],qty:['تعدادفروش','تعداد','مقدارفروش','تعدادکل','مقدار']};const find=list=>hs.findIndex(h=>list.some(a=>h===ivNorm(a)||h.includes(ivNorm(a))));const code=find(aliases.code),name=find(aliases.name),qty=find(aliases.qty);return{score:(qty>=0?3:0)+(name>=0?2:0)+(code>=0?1:0),code,name,qty}}
async function ivReadSalesFile(event){const file=event.target.files[0];event.target.value='';if(!file)return;try{const XLSX=await ivLoadXlsx(),buffer=await file.arrayBuffer(),wb=XLSX.read(buffer,{type:'array',raw:false});let best=null;wb.SheetNames.forEach(sheetName=>{const rows=XLSX.utils.sheet_to_json(wb.Sheets[sheetName],{header:1,raw:false,defval:'',blankrows:false});for(let r=0;r<Math.min(rows.length,30);r++){const headers=(rows[r]||[]).map(ivText),test=ivHeaderScore(headers);if(!best||test.score>best.score)best={sheetName,rows,headerRow:r,headers,...test}}});if(!best||best.score<3)throw Error('ردیف عنوان یا ستون تعداد در فایل پیدا نشد');inventoryPendingImport={fileName:file.name,fileSize:file.size,lastModified:file.lastModified,sheetName:best.sheetName,rows:best.rows,headerRow:best.headerRow,headers:best.headers,auto:{code:best.code,name:best.name,qty:best.qty}};ivOpenSalesMapping()}catch(e){toast(e.message||'خواندن فایل فروش انجام نشد',true)}}
function ivOpenSalesMapping(){const p=inventoryPendingImport,opts=p.headers.map((h,i)=>`<option value="${i}">${esc(h||`ستون ${i+1}`)}</option>`).join('');ivOpenModal('تنظیم ستون‌های گزارش فروش',`<div class="iv-import-summary"><div><span>فایل</span><b style="font-size:13px">${esc(p.fileName)}</b></div><div><span>شیت</span><b style="font-size:13px">${esc(p.sheetName)}</b></div><div><span>ردیف عنوان</span><b>${ivFmt(p.headerRow+1,0)}</b></div><div><span>ردیف داده</span><b>${ivFmt(Math.max(0,p.rows.length-p.headerRow-1),0)}</b></div></div><div class="form-grid"><div class="field"><label>ستون کد آیتم</label><select id="iv_imp_code"><option value="-1">ندارد</option>${opts}</select></div><div class="field"><label>ستون نام آیتم</label><select id="iv_imp_name"><option value="-1">ندارد</option>${opts}</select></div><div class="field"><label>ستون تعداد فروش</label><select id="iv_imp_qty">${opts}</select></div></div><div class="iv-info" style="margin-top:12px">حداقل یکی از ستون‌های کد یا نام و حتماً ستون تعداد را انتخاب کنید.</div>`,`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" onclick="ivConfirmSalesImport()">ورود فروش</button>`);$('iv_imp_code').value=String(p.auto.code);$('iv_imp_name').value=String(p.auto.name);$('iv_imp_qty').value=String(p.auto.qty)}
async function ivConfirmSalesImport(){const p=ivPeriod(),src=inventoryPendingImport,codeIx=+$('iv_imp_code').value,nameIx=+$('iv_imp_name').value,qtyIx=+$('iv_imp_qty').value;if(qtyIx<0||(codeIx<0&&nameIx<0))return toast('ستون تعداد و حداقل کد یا نام الزامی است',true);const fingerprint=`${src.fileName}|${src.fileSize}|${src.lastModified}`;if(p.salesImports.some(x=>x.fingerprint===fingerprint)&&!confirm('این فایل قبلاً وارد شده است. دوباره وارد شود؟'))return;const aggregated=new Map();src.rows.slice(src.headerRow+1).forEach(row=>{const code=codeIx>=0?ivText(row[codeIx]):'',name=nameIx>=0?ivText(row[nameIx]):'',qty=ivNum(row[qtyIx]);if((!code&&!name)||qty===0)return;const menuItemId=ivAutoMatch(code,name),key=`${ivNorm(code)}|${ivNorm(name)}|${menuItemId}`;if(!aggregated.has(key))aggregated.set(key,{sourceCode:code,sourceName:name,quantity:0,menuItemId});aggregated.get(key).quantity+=qty});const importId=ivUid('IMPORT',p.salesImports),lines=[...aggregated.values()].map((x,i)=>({id:`${importId}-L${String(i+1).padStart(4,'0')}`,importId,...x})),matchedCount=lines.filter(x=>x.menuItemId).length,unmatchedCount=lines.length-matchedCount;p.salesImports.unshift({id:importId,fileName:src.fileName,sheetName:src.sheetName,fingerprint,importedAt:new Date().toISOString(),rowsCount:lines.length,matchedCount,unmatchedCount});p.salesLines.push(...lines);inventoryPendingImport=null;await ivCommit('ورود گزارش فروش سپیدز');inventoryUI.tab='sales';renderView();toast(`${lines.length} ردیف فروش وارد شد`)}
async function ivMapSalesLine(lineId,menuItemId){const p=ivPeriod(),line=p.salesLines.find(x=>x.id===lineId);if(!line)return;line.menuItemId=menuItemId;const imp=p.salesImports.find(x=>x.id===line.importId);if(imp){const lines=p.salesLines.filter(x=>x.importId===imp.id);imp.matchedCount=lines.filter(x=>x.menuItemId).length;imp.unmatchedCount=lines.length-imp.matchedCount}if(menuItemId){const existing=ivPersistentMapping(line.sourceCode,line.sourceName),o={sourceCode:line.sourceCode,sourceName:line.sourceName,menuItemId,updatedAt:new Date().toISOString()};if(existing)Object.assign(existing,o);else inventoryState.itemMappings.push({id:ivUid('MAP',inventoryState.itemMappings),...o})}await ivSaveData(false,'تطبیق آیتم فروش');renderView();toast('تطبیق ذخیره شد')}
async function ivDeleteSalesLine(id){const p=ivPeriod(),line=p.salesLines.find(x=>x.id===id);if(!line||!confirm('این ردیف فروش حذف شود؟'))return;const importId=line.importId;p.salesLines=p.salesLines.filter(x=>x.id!==id);const imp=p.salesImports.find(x=>x.id===importId);if(imp){const lines=p.salesLines.filter(x=>x.importId===imp.id);imp.rowsCount=lines.length;imp.matchedCount=lines.filter(x=>x.menuItemId).length;imp.unmatchedCount=lines.length-imp.matchedCount}await ivSaveData(false,'حذف ردیف فروش');renderView();toast('ردیف حذف شد')}
async function ivDeleteSalesImport(id){const p=ivPeriod(),imp=p.salesImports.find(x=>x.id===id);if(!imp||!confirm(`فایل «${imp.fileName}» و تمام ردیف‌های آن حذف شود؟`))return;p.salesImports=p.salesImports.filter(x=>x.id!==id);p.salesLines=p.salesLines.filter(x=>x.importId!==id);await ivSaveData(false,'حذف فایل فروش');renderView();toast('فایل فروش حذف شد')}
async function ivSaveSettings(){inventoryState.settings.varianceAlertPercent=Math.max(0,ivNum($('iv_set_percent').value));inventoryState.settings.varianceAlertValueToman=Math.max(0,ivNum($('iv_set_value').value));inventoryState.settings.defaultPriority=$('iv_set_priority').value;inventoryState.settings.suggestedKeywords=$('iv_set_keywords').value.split(/\n+/).map(ivText).filter(Boolean);await ivSaveData(false,'ویرایش تنظیمات مغایرت');renderView();toast('تنظیمات ذخیره شد')}
function ivExportReportCsv(){const p=ivPeriod();if(!p)return;const rows=ivMetrics(p),csv=[['ماده','اولویت','واحد','موجودی اولیه','ورود','اصلاح','مصرف تئوریک','موجودی مورد انتظار','موجودی واقعی','مغایرت','درصد مغایرت','هزینه واحد','ارزش مغایرت'],...rows.map(m=>[m.ingredientName,m.priority,m.unit,m.opening,m.receipts,m.adjustments,m.theoreticalConsumption,m.expectedClosing,m.actualClosing??'',m.varianceQuantity??'',m.variancePercent??'',m.unitCostToman,m.varianceValueToman??''])].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const b=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`inventory-variance-${p.id}.csv`;a.click();URL.revokeObjectURL(a.href)}
function ivExportJson(){inventoryState.meta.updatedAt=new Date().toISOString();const b=new Blob([JSON.stringify(inventoryState,null,2)],{type:'application/json;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='inventory-data.json';a.click();URL.revokeObjectURL(a.href)}
async function ivSaveJsonToDisk(){try{inventoryState.meta.updatedAt=new Date().toISOString();if('showSaveFilePicker'in window){if(!inventoryFileHandle)inventoryFileHandle=await window.showSaveFilePicker({suggestedName:'inventory-data.json',types:[{description:'JSON',accept:{'application/json':['.json']}}]});const w=await inventoryFileHandle.createWritable();await w.write(JSON.stringify(inventoryState,null,2));await w.close();await InventoryStorageAdapter.save(inventoryState);toast('فایل inventory-data.json ذخیره شد')}else{ivExportJson();toast('مرورگر نوشتن مستقیم را پشتیبانی نمی‌کند؛ JSON دانلود شد')}}catch(e){if(e?.name!=='AbortError')toast('ذخیره فایل انبار انجام نشد',true)}}
function ivImportJson(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{inventoryState=ivMigrate(JSON.parse(r.result));inventoryLoaded=true;await InventoryStorageAdapter.save(inventoryState);inventoryUI.periodId=inventoryState.periods[0]?.id||'';renderView();toast('JSON انبار وارد شد')}catch(err){toast('فایل JSON انبار معتبر نیست',true)}};r.readAsText(f);e.target.value=''}
function installInventoryModule(){if(typeof views==='undefined'||typeof titles==='undefined'||document.querySelector('[data-view="inventory"]'))return;titles.inventory='انبار و مغایرت‌گیری';views.inventory=viewsInventory;const sidebar=document.querySelector('.sidebar'),groups=[...sidebar.querySelectorAll('.nav-group')],ref=groups.find(x=>x.textContent.includes('گزارش و تنظیمات'));const group=document.createElement('div');group.className='nav-group';group.textContent='انبار و کنترل مصرف';const btn=document.createElement('button');btn.className='nav-btn';btn.dataset.view='inventory';btn.innerHTML='📦 <span>انبار و مغایرت‌گیری</span>';btn.onclick=()=>goView('inventory');sidebar.insertBefore(group,ref||null);sidebar.insertBefore(btn,ref||null);Object.assign(window,{getInventoryState:()=>inventoryState,getInventoryMetrics:()=>{const p=ivPeriod();return p?ivMetrics(p):[]},inventoryUI,ivEnsureLoaded,ivRefreshData,ivSaveData,ivSaveJsonToDisk,ivExportJson,ivImportJson,ivEditPeriod,ivSavePeriod,ivDeletePeriod,ivClosePeriod,ivReopenPeriod,ivToggleTracked,ivSetTrackedPriority,ivSetTrackedNotes,ivAddSuggestedTracked,ivSaveStocks,ivEditReceipt,ivSaveReceipt,ivDeleteReceipt,ivEditAdjustment,ivSaveAdjustment,ivDeleteAdjustment,ivReadSalesFile,ivConfirmSalesImport,ivMapSalesLine,ivDeleteSalesLine,ivDeleteSalesImport,ivSaveSettings,ivExportReportCsv})}
(function waitInventoryModule(){if(typeof views!=='undefined'&&typeof titles!=='undefined'&&document.querySelector('.sidebar'))installInventoryModule();else setTimeout(waitInventoryModule,60)})();
